package com.cinebook.dashboard;
import com.cinebook.auth.*;import com.cinebook.booking.*;import com.cinebook.catalog.*;import com.cinebook.events.OutboxRepository;import com.cinebook.payment.*;import com.cinebook.common.ApiException;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/dashboard")
public class DashboardController {
 private final UserRepository users;private final MovieRepository movies;private final BookingRepository bookings;private final BookingService bookingService;private final ShowtimeRepository shows;private final ShowSeatRepository inventory;private final PaymentRepository payments;private final OutboxRepository outbox;private final boolean messaging;
 public DashboardController(UserRepository u,MovieRepository m,BookingRepository b,BookingService bs,ShowtimeRepository s,ShowSeatRepository i,PaymentRepository p,OutboxRepository o,@Value("${app.messaging.enabled:false}") boolean msg){users=u;movies=m;bookings=b;bookingService=bs;shows=s;inventory=i;payments=p;outbox=o;messaging=msg;}
 @GetMapping("/summary") public Map<String,Object> summary(java.security.Principal principal){UserAccount u=users.findByEmailIgnoreCase(principal.getName()).orElseThrow(()->new ApiException(404,"USER_NOT_FOUND","User was not found"));Map<String,Object> result=new LinkedHashMap<>();result.put("role",u.getRole().name());result.put("generatedAt",Instant.now());switch(u.getRole()){
 case CUSTOMER->{result.put("confirmedBookings",bookings.countConfirmedForUser(u.getId()));result.put("bookingHistory",bookingService.history(u.getEmail()).size());result.put("upcomingShows",bookings.findAllByUserIdOrderByCreatedAtDesc(u.getId()).stream().filter(b->b.getStatus()==Booking.State.CONFIRMED&&b.getShowtime().getStartsAt().isAfter(Instant.now())).count());}
 case THEATRE_PARTNER->{result.put("managedShows",shows.findPartnerShows(u.getEmail()).size());result.put("confirmedBookings",bookings.countConfirmedForPartner(u.getId()));BigDecimal revenue=bookings.revenueForPartner(u.getId());result.put("confirmedRevenue",revenue);result.put("currency","INR");}
 case ADMIN->{result.put("users",users.count());result.put("movies",movies.count());result.put("bookings",bookings.count());result.put("confirmedRevenue",bookings.confirmedRevenue());result.put("failedPayments",payments.countByStatus(PaymentRecord.Status.FAILED));}
 case OPERATIONS->{result.put("failedPayments",payments.countByStatus(PaymentRecord.Status.FAILED));result.put("pendingPayments",payments.countByStatus(PaymentRecord.Status.PENDING));result.put("expiredHeldRows",inventory.countExpiredHeld(Instant.now()));result.put("pendingOutboxEvents",outbox.countByState("PENDING"));result.put("publishedOutboxEvents",outbox.countByState("PUBLISHED"));result.put("messagingEnabled",messaging);result.put("cleanup","Scheduled in-process cleanup enabled");}
 }return result;}
 @GetMapping("/partner/shows") public List<CatalogDtos.ShowtimeView> partnerShows(java.security.Principal p){UserAccount u=users.findByEmailIgnoreCase(p.getName()).orElseThrow(()->new ApiException(404,"USER_NOT_FOUND","User was not found"));if(u.getRole()!=Role.THEATRE_PARTNER&&u.getRole()!=Role.ADMIN)throw new ApiException(403,"FORBIDDEN","Partner role required");return shows.findPartnerShows(p.getName()).stream().map(CatalogDtos::show).toList();}
}
